export const MAP_VIEWBOX = [0, 0, 600, 720];
const order = ['11','26','27','28','29','30','31','36','41','51','43','44','52','46','47','48','50'];
const aliases = { '51': ['강원도'], '52': ['전라북도'], '50': ['제주도'], '36': ['세종시'] };
const raw = Uint8Array.from(atob(packedArcs), character => character.charCodeAt(0));
let cursor = 0;
function readUint() {
  let value = 0, multiplier = 1, byte;
  do { byte = raw[cursor++]; value += (byte & 127) * multiplier; multiplier *= 128; } while (byte & 128);
  return value;
}
const signed = value => value & 1 ? -(value + 1) / 2 : value / 2;
const mercatorY = latitude => -Math.log(Math.tan(Math.PI / 4 + latitude * Math.PI / 360));
const west = transform.translate[0];
const east = transform.translate[0] + transform.scale[0] * 59999;
const north = mercatorY(transform.translate[1] + transform.scale[1] * 59999);
const south = mercatorY(transform.translate[1]);
const longitudeScale = Math.PI / 180;
const projectedWidth = (east - west) * longitudeScale;
const projectedHeight = south - north;
const scale = Math.min(552 / projectedWidth, 672 / projectedHeight);
const offsetX = (600 - projectedWidth * scale) / 2;
const offsetY = (720 - projectedHeight * scale) / 2;
const round = value => Math.round(value * 100) / 100;
function project(coordinate) {
  return [round(offsetX + (coordinate[0] - west) * longitudeScale * scale), round(offsetY + (mercatorY(coordinate[1]) - north) * scale)];
}
const arcs = [];
while (cursor < raw.length) {
  const count = readUint(), points = [];
  let x = 0, y = 0;
  for (let index = 0; index < count; index++) {
    x += signed(readUint()); y += signed(readUint());
    points.push(project([x * transform.scale[0] + transform.translate[0], y * transform.scale[1] + transform.translate[1]]));
  }
  arcs.push(points);
}
function geometry(geometry) {
  const polygons = geometry.type === 'Polygon' ? [geometry.arcs] : geometry.arcs;
  const bounds = [Infinity, Infinity, -Infinity, -Infinity];
  const paths = [];
  for (const polygon of polygons) for (const ring of polygon) {
    const points = [];
    for (const id of ring) {
      const arc = id < 0 ? arcs[~id].slice().reverse() : arcs[id];
      points.push(...(points.length ? arc.slice(1) : arc));
    }
    const distinct = points.filter((point, index) => !index || point[0] !== points[index - 1][0] || point[1] !== points[index - 1][1]);
    if (distinct.length < 3) continue;
    for (const point of distinct) {
      bounds[0] = Math.min(bounds[0], point[0]); bounds[1] = Math.min(bounds[1], point[1]);
      bounds[2] = Math.max(bounds[2], point[0]); bounds[3] = Math.max(bounds[3], point[1]);
    }
    paths.push('M' + distinct.map(point => point.join(',')).join('L') + 'Z');
  }
  return { path: paths.join(''), bounds };
}
const displayDistrict = name => name.replace(/^(.+?시)(.+구)$/, '$1 $2');
export const REGIONS = objects.regions.geometries.map(item => {
  const code = item.properties.sidocd;
  return { code, name: regionNames[code], aliases: aliases[code] || [], ...geometry(item), center: project(labelPoints.regions[code]) };
}).sort((a, b) => order.indexOf(a.code) - order.indexOf(b.code));
export const DISTRICTS = objects.districts.geometries.map(item => {
  const code = item.properties.sggcd;
  return { code, sidoCode: item.properties.sidocd, name: displayDistrict(item.properties.sggnm), rawName: item.properties.sggnm, ...geometry(item), center: project(labelPoints.districts[code]) };
}).sort((a, b) => a.name.localeCompare(b.name, 'ko'));
export function getDistricts(sido) {
  const region = REGIONS.find(item => item.code === sido || item.name === sido || item.aliases.includes(sido));
  return region ? DISTRICTS.filter(item => item.sidoCode === region.code) : [];
}

export function districtAtLocation(longitude, latitude) {
  const [x, y] = project([longitude, latitude]);
  const context = document.createElement('canvas').getContext('2d');
  if (!context) return null;
  return DISTRICTS.find(({ bounds, path }) =>
    x >= bounds[0] && y >= bounds[1] && x <= bounds[2] && y <= bounds[3]
    && context.isPointInPath(new Path2D(path), x, y, 'evenodd')
  ) ?? null;
}
